"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["90743"],{81986(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.cronograma.recurso_sem_banca","status":422,"titulo":"Fase ou etapa com recurso exige banca de an\xe1lise de recursos"},"descricao":{"codigo":"uniplus.selecao.cronograma.recurso_sem_banca","requisitos":["UNI-REQ-0274"],"oQueAconteceu":["O cronograma tem prazo de recurso em uma fase ou em uma etapa, e nenhuma banca\\nde an\xe1lise de recursos o julga. Todo recurso previsto no edital exige essa banca\\n(UNI-REQ-0274), porque quem integra a banca \xe9 quem tem acesso aos dados dos\\ncandidatos para analis\xe1-lo. Sem ela, o recurso de quem recorre ficaria sem quem\\no analise, e o edital n\xe3o \xe9 publicado.","A banca que atende o recurso \xe9 declarada assim:","- **recurso da fase:** a banca de an\xe1lise de recursos declarada na pr\xf3pria\\n  fase;\\n- **recurso da etapa:** a banca de an\xe1lise de recursos declarada na pr\xf3pria\\n  etapa ou, na falta dela, na fase da etapa. Quando existe nas duas, o recurso\\n  da etapa \xe9 julgado pela banca da etapa. Banca declarada s\xf3 em outra etapa n\xe3o\\n  atende.","A confer\xeancia roda no congelamento do processo: na publica\xe7\xe3o e na retifica\xe7\xe3o\\nem ato \xfanico. A grava\xe7\xe3o do cronograma n\xe3o a faz. A recusa vem como o c\xf3digo desta p\xe1gina no corpo da\\nresposta, e n\xe3o na lista `errors[]`; ela aponta uma pend\xeancia por vez, a\\nprimeira que encontra, e cita a fase ou a etapa que est\xe1 sem banca."],"comoResolver":["Declare a banca de an\xe1lise de recursos onde o recurso \xe9 julgado:","- na fase, quando todos os recursos dela, e das etapas que n\xe3o t\xeam banca\\n  pr\xf3pria, s\xe3o analisados pela mesma banca;\\n- na etapa, quando ela tem banca de recurso pr\xf3pria.","Declare a banca com a regra de delibera\xe7\xe3o do edital, que tamb\xe9m \xe9 conferida:\\n[regra obrigat\xf3ria](/erros/uniplus.selecao.banca.regra_de_deliberacao_obrigatoria)\\ne [m\xednimo de integrantes](/erros/uniplus.selecao.banca.integrantes_abaixo_do_minimo).\\nSe o certame n\xe3o admite recurso naquela fase ou etapa, retire o prazo de\\nrecurso em vez de declarar a banca.","O painel de conformidade aponta o recurso sem banca antes da publica\xe7\xe3o, no item\\n`cronograma_recurso_com_banca_de_analise`."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Cronograma"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);